using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitRecipientTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void EachPostAnswersOnlyItsOwnUnit(int index){var s=Away();var before=NewGameMilitary.KnownMilitary(s.DiagnosticSnapshot());var d=Dispatch(s,index);Assert.Equal(NewGameMilitary.UnitIds[index],d.Recipient);At(s,d.DueAt);var w=s.DiagnosticSnapshot();var receipt=w.NewMilitary!.UnitInquiry!.Receipts.Last();Assert.True(receipt.Delivered);Assert.False(receipt.Applied);var answer=Answer(w,receipt);Assert.Equal(d.Recipient.Value,answer.Unit);Assert.Equal(NewGameMilitary.StrengthAt(w,index,s.Seconds),answer.Soldiers);Assert.Equal(NewGameMilitary.Position(w,index,s.Seconds),answer.Position);Assert.False(MessageFlow.Knows(w.Messaging,receipt.ReplyMessage,w.PlayerControl.Value));Assert.Equal(before,NewGameMilitary.KnownMilitary(w));At(s,receipt.ReplyDueAt);w=s.DiagnosticSnapshot();var learned=NewGameMilitary.KnownMilitary(w);Assert.Equal("letter/"+receipt.ReplyMessage,learned.Single(r=>r.Unit==d.Recipient).Evidence);Assert.Equal(answer.Position,learned.Single(r=>r.Unit==d.Recipient).Position);Assert.Equal(before.Where(r=>r.Unit!=d.Recipient),learned.Where(r=>r.Unit!=d.Recipient));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ForgedDestinationAndPolicyAreAtomic(int kind){var s=Away();var input=Query(s,1);var known=input.InquiryTarget!.Known;input=kind switch{0=>input with{InquiryTarget=input.InquiryTarget with{Contract="unknown"}},1=>input with{InquiryTarget=input.InquiryTarget with{Known=known with{Position=new(known.Position.X+1,known.Position.Y)}}},2=>input with{InquiryTarget=input.InquiryTarget with{Known=known with{ObservedAt=known.ObservedAt+1}}},3=>input with{InquiryTarget=input.InquiryTarget with{Known=known with{Evidence="letter/unknown"}}},4=>input with{InquiryTarget=input.InquiryTarget with{Known=known with{Unit=new("unit:unknown")}}},_=>input with{InquiryTarget=input.InquiryTarget with{Known=known with{Unit=NewGameMilitary.UnitIds[2]}}}};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void LegacyQueryStillTargetsMainPostAndOmitsNewFields(){var s=Away();var input=Input(s,NewMilitaryAction.InquireUnitKnown);Assert.DoesNotContain("InquiryTarget",System.Text.Encoding.UTF8.GetString(ContractJson.Write(input)));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();var d=w.NewMilitary!.UnitInquiry!.Dispatches.Last();Assert.Equal(NewGameMilitary.UnitIds[0],d.Recipient);var body=ContractJson.Read<UnitPostInquiry>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==d.Message).Body));Assert.Null(body.Target);Assert.DoesNotContain("Target",System.Text.Encoding.UTF8.GetString(ContractJson.Write(body)));new WorldSession(w);}
 [Fact]public void WingDoesNotQuoteMainPostOriginals(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);var d=Dispatch(s,1);var w=s.DiagnosticSnapshot();var body=ContractJson.Read<UnitPostInquiry>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==d.Message).Body));Assert.Empty(body.Originals);Assert.Equal(NewGameMilitary.UnitIds[1],body.Target!.Known.Unit);Assert.NotEmpty(w.NewMilitary!.Withdrawal!.Dispatches);}
 [Fact]public void StaleAddressNeverFollowsMovingTarget(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);var recall=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();At(s,recall.DueAt+5);var d=Dispatch(s,2);var fixedPoint=d.Destination;At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.NotEqual(fixedPoint,NewGameMilitary.Position(w,2,s.Seconds));Assert.False(w.NewMilitary!.UnitInquiry!.Receipts.Last().Delivered);Assert.Equal(fixedPoint,w.NewMilitary.UnitInquiry.Dispatches.Last().Destination);new WorldSession(w);}
 [Theory][InlineData(1)][InlineData(2)]public void LostReplyReturnsToItsOwnWingBeforeRetry(int index){var s=Away();var d=Dispatch(s,index);At(s,d.DueAt);var receipt=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-20000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,receipt.ReplyDueAt);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,receipt.ReplyMessage,w.PlayerControl.Value));var failure=w.NewMilitary!.ReplyRecovery!.Flights.Last(f=>f.Kind==UnitReplyLeg.FailureReport);Assert.Equal(d.Destination,failure.Destination);At(s,failure.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,failure.Message,d.Recipient.Value));Assert.False(MessageFlow.Knows(w.Messaging,failure.Message,NewGameMilitary.UnitIds[0].Value));var retry=w.NewMilitary!.ReplyRecovery!.Flights.Last(f=>f.Kind==UnitReplyLeg.Retry);Assert.Equal(d.Destination,retry.Origin);Send(s,NewMilitaryAction.PersonalHome);At(s,retry.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,receipt.ReplyMessage,w.PlayerControl.Value));Assert.Equal(d.Recipient.Value,Answer(w,receipt).Unit);new WorldSession(w);}
 [Fact]public void SavedRecipientTamperIsRejected(){var s=Away();var d=Dispatch(s,1);var w=s.DiagnosticSnapshot();w.NewMilitary!.UnitInquiry!.Dispatches[0]=d with{Recipient=NewGameMilitary.UnitIds[0]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void RestoredFlightHasSameRecipientAndFuture(){var s=Away();var d=Dispatch(s,2);At(s,d.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());At(s,d.DueAt);At(restored,d.DueAt);long reply=s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last().ReplyDueAt;At(s,reply+2);At(restored,reply+2);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));}
 [Fact]public void SameRequestIsIdempotentEvenAfterTimeAndRevisionChange(){var s=Away();var input=Query(s,1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);At(s,s.Seconds+1);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,0).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,s.DecideNewMilitary(input with{InquiryTarget=Query(s,2).InquiryTarget},s.PlayerControl,s.Revision).Code);}
 [Fact]public void InquiryEvidenceCannotBeUsedForPersonalMoveOrHomeQuery(){var s=Away();var input=Query(s,1);string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input with{Action=NewMilitaryAction.PersonalMove},s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input with{Action=NewMilitaryAction.InquireUnitHome},s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void UnknownReplyDoesNotBecomeAddressEvidence(){var s=Away();var d=Dispatch(s,1);At(s,d.DueAt);var w=s.DiagnosticSnapshot();var receipt=w.NewMilitary!.UnitInquiry!.Receipts.Last();Assert.DoesNotContain(NewGameMilitary.KnownMilitary(w),r=>r.Evidence=="letter/"+receipt.ReplyMessage);Assert.DoesNotContain("返書（",NewGameMilitary.UnitInquiryStatus(w));}
 [Fact]public void SelectedQueryJsonRoundTripsItsVersionAndEvidence(){var s=Away();var input=Query(s,2);Assert.Equal(input,ContractJson.Read<NewMilitaryInput>(ContractJson.Write(input)));Assert.Equal(NewGameMilitary.UnitRecipientContract,input.InquiryTarget!.Contract);}
}
